+static constexpr size_t MAX_N = 2000000;
+static constexpr size_t RADIX_BITS   = 8;
+static constexpr size_t BUCKET_COUNT = 1u << RADIX_BITS;   // 256
+static constexpr size_t INSERTION_SORT_THRESHOLD = 64;
+
+// tiny insertion sort – in‑place, used for n ≤ INSERTION_SORT_THRESHOLD
+static void insertion_sort(uint32_t* a, size_t n) {
+    for (size_t i = 1; i < n; ++i) {
+        uint32_t key = a[i];
+        size_t j = i;
+        while (j > 0 && a[j - 1] > key) {
+            a[j] = a[j - 1];
+            --j;
+        }
+        a[j] = key;
+    }
